import type { Role } from '../app'
import type { Record, TableName } from '../db'

/** @interface */
export type UiAction<T extends TableName> = Now.Internal.WithIdAndMetadata<
    {
        /**
         * table on which UI Action appears
         */
        table: T
        /**
         * name of the UI Action. It must be unique within the table
         */
        name: string
        /**
         * unique string that can be referenced in scripts
         */
        actionName?: string
        /**
         * If true, the UI Action is enabled
         */
        active?: boolean
        /**
         * UI action on form view and related properties.
         * When set to `true`, the action will be executable in a form via programmatic calls without appearing in the UI (only applicable in UI26).
         * When set as an object, the action will be displayed in a form view following the specified configuration.
         */
        form?:
            | {
                  showButton?: boolean
                  showLink?: boolean
                  showContextMenu?: boolean
                  style?: 'primary' | 'destructive' | 'unstyled' | 'primary-ai' | 'secondary-ai'
                  /**
                   * Name of the icon to display on the button. For the list of available icons, go to
                   * `/styles/retina_icons/retina_icons.html` on your instance.
                   */
                  iconName?: string
                  /**
                   * When true, the button will display only the icon, ignoring the 'Name' field.
                   * Remember to add a separate tooltip to the UI action itself to describe its function to users.
                   */
                  showIconOnly?: boolean
              }
            | true
        /**
         * UI action on list view and related properties.
         * When set to `true`, the action will be executable in a list via programmatic calls without appearing in the UI (only applicable in UI26).
         * When set as an object, the action will be displayed in a list view following the specified configuration.
         */
        list?:
            | {
                  showButton?: boolean
                  showLink?: boolean
                  showContextMenu?: boolean
                  style?: 'primary' | 'destructive' | 'unstyled' | 'primary-ai' | 'secondary-ai'
                  showListChoice?: boolean
                  showBannerButton?: boolean
                  showSaveWithFormButton?: boolean
                  /**
                   * Name of the icon to display on the button. For the list of available icons, go to
                   * `/styles/retina_icons/retina_icons.html` on your instance.
                   */
                  iconName?: string
                  /**
                   * When true, the button will display only the icon, ignoring the 'Name' field.
                   * Remember to add a separate tooltip to the UI action itself to describe its function to users.
                   */
                  showIconOnly?: boolean
              }
            | true
        /**
         * If client side script and related properties
         */
        client?: {
            isClient?: boolean
            isUi11Compatible?: boolean
            isUi16Compatible?: boolean
            onClick?: string
        }
        /**
         * UI action on workspace configuration and related properties
         */
        workspace?: {
            isConfigurableWorkspace?: boolean
            showFormButtonV2?: boolean
            showFormMenuButtonV2?: boolean
            clientScriptV2?: string
        }
        /**
         * Action being overridden by the current record
         */
        overrides?: string | Record<'sys_ui_action'>
        /**
         * Checked, the UI Action appears in insert
         */
        showInsert?: boolean
        /**
         * Checked, the UI Action appears in update
         */
        showUpdate?: boolean
        /**
         * Checked, the UI Action appears in insert, update, query or update multiple(bulk edit) mode.
         */
        showQuery?: boolean
        /**
         * Checked, the UI Action appears in insert, update, query or update multiple(bulk edit) mode.
         */
        showMultipleUpdate?: boolean
        /**
         * A script or condition that determines whether the UI Action is visible.
         */
        condition?: string
        /**
         * Script runs automatically as part of the UI Action when the client calls it. Note:
         * server module scripts (sys_module) can only be used on server-side UI Actions.
         */
        script?: string | ((current: any, ...params: any[]) => void)
        /**
         * text field used by developers and admins to add internal notes
         */
        comments?: string
        /**
         *  messages field holds user facing messages or text that are accessed via the `getMessage` or `getMessages` API in client scripts
         */
        messages?: string[]
        /**
         * a tooltip or hover text that appears when users hover their mouse pointer over
         */
        hint?: string
        /**
         * Determines the order in which the UI Action appears. Lower values show first.
         */
        order?: number
        /**
         * Checked, script in a UI Action runs in an isolated script
         */
        isolateScript?: boolean
        /**
         *  stores roles associated with a UI Action, defining which users can see or execute that UI Action based on their roles
         * TODO: Add support for sysid references
         */
        roles?: (string | Role)[]
        /**
         * Specifies views in which UI action to be included
         * TODO: Add support for sysid references
         */
        includeInViews?: string[]
        /**
         * Specifies views from which UI action to be excluded
         * TODO: Add support for sysid references
         */
        excludeFromViews?: string[]
    } & Now.Internal.Meta
>

/**
 * @param config
 * @constructor
 */

export function UiAction<const T extends TableName>(config: UiAction<T>) {
    return config
}
